if o.Side == Sell {
	if _, ok := addInt64(e.cash, amount); !ok {
		e.appendRecord(Record{
			Kind:       RecordRejected,
			Symbol:     o.Symbol,
			Side:       o.Side,
			OrderID:    o.ID,
			TradeID:    t.TradeID,
			Qty:        t.Qty,
			TradePrice: t.Price,
			Reason: fmt.Sprintf("卖出成交 %d（价格 %d × 数量 %d = %d）入账将使现金余额 %d 加成交所得后超出 int64 范围，整笔拒绝",
				t.TradeID, t.Price, t.Qty, amount, e.cash),
